import assert from 'node:assert/strict';
import {Client,base,requests,server,setActions,until,held,delay} from './codex-fixture';
const home=base+'/goals-disabled-'+Date.now();let c=new Client(home);const count=()=>requests.filter(r=>r.generate!==false).length;
try{await c.init();const {thread}=await c.start();setActions('hold');const t=await c.turn(thread.id,'old active goal fixture');await until(()=>held.length===1);await c.call('thread/goal/set',{threadId:thread.id,origin:'user',objective:'old active goal',status:'active'});await c.call('turn/interrupt',{threadId:thread.id,turnId:t.turn.id});await c.done(t.turn.id);await c.close();const before=count();c=new Client(home,true,'',false);await c.init();await c.call('thread/read',{threadId:thread.id,includeTurns:false});await c.call('thread/resume',{threadId:thread.id,excludeTurns:true});await delay(300);assert.equal(count(),before);await assert.rejects(()=>c.call('thread/goal/set',{threadId:thread.id,origin:'user',status:'active'}));for(let n=0;n<2;n++){const f=await c.turn(thread.id,'fresh disabled-goal input '+n);assert.equal((await c.done(f.turn.id)).status,'completed');assert.ok(c.events.some(e=>e.method==='item/completed'&&e.params.turnId===f.turn.id&&e.params.item.text==='offline reply'));const body=requests.filter(r=>r.generate!==false).at(-1);assert.ok(!body.tools.some((t:any)=>['create_goal','update_goal','get_goal'].includes(t.name)));await delay(150);assert.equal(count(),before+n+1);}console.log(JSON.stringify({case:'Codex-disabled-goal-baseline',activeGoalHistoryResumeInert:true,goalMutationRejected:true,goalToolsAbsent:true,launchPinOverridesHome:true,retainedTwoTurns:true}));
}finally{await c.close();server.stop(true)}
